import React from "react";

const Main = ({ tasks, setTasks }) => {
  return (
    <div className="main">
      <input />
      <div className="buttons">
        <button className="addTodo" title="Добавление новой задачи">
          <span>ДОБАВИТЬ ЗАДАЧУ</span>
        </button>
        <button className="removeTodo" title="Удаление всех выполненных задач">
          УДАЛИТЬ ЗАДАЧИ
        </button>
      </div>
      <div className="todolist">
        {tasks.map((task) => {
          return (
            <div className="task">
              <input type="checkbox" />
              <label></label>
            </div>
          );
        })}
      </div>
    </div>
  );
};

export default Main;
